WITH checks(kind,d1,d2,d3,d4) AS (SELECT 'schema', type, name, tbl_name, coalesce(sql,'') FROM sqlite_schema WHERE name IN ('t1','t1_i1','t1_i2','t1_i3','t2','t2_i1','t2_i2','t2_i3') UNION ALL SELECT 'data-t1', typeof(a)||':'||quote(a), typeof(b)||':'||quote(b), typeof(c)||':'||quote(c), '' FROM t1 UNION ALL SELECT 'data-t2', typeof(x)||':'||quote(x), typeof(y)||':'||quote(y), typeof(z)||':'||quote(z), '' FROM t2) SELECT kind,d1,d2,d3,d4 FROM checks ORDER BY kind,d1,d2,d3,d4;